const { Given, When, Then } = require('@cucumber/cucumber');

// ── Background ──────────────────────────────────────────────────

Given('the app is loaded', function () {
  // world.js Before hook already loads the app via loadApp()
  // This step exists as a readable declaration; the actual work
  // happens in the Before hook.
});

// ── Helpers ─────────────────────────────────────────────────────

function queryAll(root, selector) {
  if (!root) return [];
  const result = root.querySelectorAll(selector);
  return Array.from(result);
}

function query(root, selector) {
  return root ? root.querySelector(selector) : null;
}

function todoItems() {
  const list = this.document.querySelector('.todo-list');
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

function firstTodo() {
  const items = todoItems.call(this);
  return items.length > 0 ? items[0] : null;
}

function getVisible(el) {
  if (!el) return 'none';
  const style = this.window.getComputedStyle(el);
  return style.display;
}

function isVisible(el) {
  if (!el) return false;
  const style = this.window.getComputedStyle(el);
  // A hidden element has display:none or its offsetParent is null
  return style.display !== 'none' && style.visibility !== 'hidden';
}

function todoTitle(el) {
  const label = el.querySelector('label');
  return label ? label.textContent.trim() : '';
}

function todoCompleted(el) {
  return el.classList.contains('completed');
}

// ── No todos ────────────────────────────────────────────────────

Given('there are no todos', function () {
  // Clear localStorage and re-init the app
  this.window.localStorage.removeItem('todos-vanillajs');
  if (this.window.__todoApp) {
    this.window.__todoApp.todos = [];
    this.window.__todoApp.filter = 'all';
    this.window.__todoApp.render();
  }
});

Then('{string} is not visible', function (selector) {
  const el = query(this.document, selector);
  if (!el) return; // element not in DOM = not visible
  const visible = isVisible.call(this, el);
  if (visible) {
    throw new Error(`Expected "${selector}" to not be visible, but it is visible`);
  }
});

// ── New todo ────────────────────────────────────────────────────

When('I type {string} into {string}', function (text, selector) {
  const input = query(this.document, selector);
  if (!input) throw new Error(`Input "${selector}" not found`);
  input.value = text;
  // Dispatch input event so app can react
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('New todo input not found');
  const ev = new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(ev);
  // Also dispatch keydown/keyup for compatibility
  const ev2 = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(ev2);
});

Then('I see {int} todo in the list', function (count) {
  const items = todoItems.call(this);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todo in list, found ${items.length}`);
  }
});

Then('I see {int} todos in the list', function (count) {
  const items = todoItems.call(this);
  if (items.length !== count) {
    throw new Error(`Expected ${count} todos in list, found ${items.length}`);
  }
});

Then('the new todo has title {string}', function (expected) {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos in list');
  const title = todoTitle(items[items.length - 1]);
  if (title !== expected) {
    throw new Error(`Expected todo title "${expected}", got "${title}"`);
  }
});

Then('the new todo is not completed', function () {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos in list');
  const last = items[items.length - 1];
  const toggle = last.querySelector('.toggle');
  if (toggle && toggle.checked) {
    throw new Error('Expected new todo to be not completed, but it is completed');
  }
  if (last.classList.contains('completed')) {
    throw new Error('Expected new todo to be not completed, but it has completed class');
  }
});

Then('the input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('New todo input not found');
  if (input.value !== '') {
    throw new Error(`Expected input to be cleared, got "${input.value}"`);
  }
});

// ── Multiple todos setup ────────────────────────────────────────

Given('the following todos exist:', function (dataTable) {
  const self = this;
  const todos = dataTable.hashes();
  // Create todos via the UI (type title, press Enter)
  todos.forEach(function (todo) {
    var input = self.document.querySelector('.new-todo');
    if (!input) throw new Error('New todo input not found');
    input.value = todo.title;
    input.dispatchEvent(new self.window.Event('input', { bubbles: true }));
    input.dispatchEvent(new self.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
    input.dispatchEvent(new self.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  });
  // Mark completed todos by clicking their toggle
  todos.forEach(function (todo, index) {
    if (todo.completed === 'true') {
      var items = todoItems.call(self);
      if (items.length > index) {
        var toggle = items[index].querySelector('.toggle');
        if (toggle) toggle.click();
      }
    }
  });
});

When('I click {string}', function (selector) {
  const el = query(this.document, selector);
  if (!el) throw new Error(`Element "${selector}" not found`);
  el.click();
});

Then('all todos are completed', function () {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos');
  items.forEach((item, i) => {
    if (!item.classList.contains('completed')) {
      throw new Error(`Expected todo ${i} to be completed, but it is not`);
    }
    const toggle = item.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      throw new Error(`Expected toggle for todo ${i} to be checked, but it is not`);
    }
  });
});

Then('{string} is checked', function (selector) {
  const el = query(this.document, selector);
  if (!el) throw new Error(`Element "${selector}" not found`);
  if (!el.checked) {
    throw new Error(`Expected "${selector}" to be checked, but it is not`);
  }
});

Then('{string} is not checked', function (selector) {
  const el = query(this.document, selector);
  if (!el) throw new Error(`Element "${selector}" not found`);
  if (el.checked) {
    throw new Error(`Expected "${selector}" to not be checked, but it is checked`);
  }
});

When('I mark the last incomplete todo as completed', function () {
  const items = todoItems.call(this);
  // Find the last incomplete todo
  let target = null;
  for (let i = items.length - 1; i >= 0; i--) {
    if (!items[i].classList.contains('completed')) {
      target = items[i];
      break;
    }
  }
  // If all are already completed, there is nothing to do
  if (!target) return;
  const toggle = target.querySelector('.toggle');
  if (!toggle) throw new Error('Toggle not found on todo');
  toggle.click();
});

When('I uncheck the first todo', function () {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos');
  const first = items[0];
  const toggle = first.querySelector('.toggle');
  if (!toggle) throw new Error('Toggle not found on first todo');
  toggle.click();
});

// ── Item interactions ──────────────────────────────────────────

When('I click the toggle for the first todo', function () {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos');
  const toggle = items[0].querySelector('.toggle');
  if (!toggle) throw new Error('Toggle not found on first todo');
  toggle.click();
});

Then('the first todo has class {string}', function (cls) {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  if (!first.classList.contains(cls)) {
    throw new Error(`Expected first todo to have class "${cls}"`);
  }
});

When('I click the destroy button for the first todo', function () {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos');
  const destroy = items[0].querySelector('.destroy');
  if (!destroy) throw new Error('Destroy button not found');
  destroy.click();
});

// ── Counter ─────────────────────────────────────────────────────

Then('the todo count shows {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  if (!el) throw new Error('Todo count element not found');
  const text = el.textContent.trim().replace(/\s+/g, ' ');
  if (text !== expected) {
    throw new Error(`Expected todo count "${expected}", got "${text}"`);
  }
});

// ── Clear completed ─────────────────────────────────────────────

Then('the remaining todo has title {string}', function (expected) {
  const items = todoItems.call(this);
  if (items.length === 0) throw new Error('No todos remaining');
  const title = todoTitle(items[0]);
  if (title !== expected) {
    throw new Error(`Expected remaining todo title "${expected}", got "${title}"`);
  }
});

// ── Editing ─────────────────────────────────────────────────────

When('I double-click the first todo label', function () {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const label = first.querySelector('label');
  if (!label) throw new Error('Label not found on first todo');
  const ev = new this.window.MouseEvent('dblclick', { bubbles: true, detail: 2 });
  label.dispatchEvent(ev);
});

When('I type {string} into the editing input', function (text) {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const editInput = first.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter in the edit field', function () {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const editInput = first.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  const ev = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  editInput.dispatchEvent(ev);
});

Then('the first todo has title {string}', function (expected) {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const title = todoTitle(first);
  if (title !== expected) {
    throw new Error(`Expected first todo title "${expected}", got "${title}"`);
  }
});

Then('the first todo does not have class {string}', function (cls) {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  if (first.classList.contains(cls)) {
    throw new Error(`Expected first todo to not have class "${cls}"`);
  }
});

When('the editing input loses focus', function () {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const editInput = first.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  const ev = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(ev);
});

When('I press Escape in the edit field', function () {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  const editInput = first.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  const ev = new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true });
  editInput.dispatchEvent(ev);
});

// ── Routing ─────────────────────────────────────────────────────

When('I navigate to {string}', function (hash) {
  // world.js navigate method handles hashchange dispatch
  this.navigate(hash);
});

Then('the {string} filter link has class {string}', function (filterName, cls) {
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  links.forEach(link => {
    if (link.textContent.trim() === filterName) {
      found = true;
      if (!link.classList.contains(cls)) {
        throw new Error(`Expected "${filterName}" filter link to have class "${cls}"`);
      }
    }
  });
  if (!found) {
    throw new Error(`Filter link "${filterName}" not found`);
  }
});

// ── Persistence ────────────────────────────────────────────────

When('the page is reloaded', function () {
  // Simulate page reload: re-init the app from localStorage
  this.document.location.reload();
  // Re-run the app initialization
  if (this.window.__todoApp) {
    this.window.__todoApp.todos = JSON.parse(this.window.localStorage.getItem('todos-vanillajs') || '[]');
    this.window.__todoApp.filter = 'all';
    this.window.__todoApp.render();
    this.window.__todoApp.bindEvents();
  }
});

Then('the first todo is not completed', function () {
  const first = firstTodo.call(this);
  if (!first) throw new Error('No todos');
  if (first.classList.contains('completed')) {
    throw new Error('Expected first todo to not be completed');
  }
  const toggle = first.querySelector('.toggle');
  if (toggle && toggle.checked) {
    throw new Error('Expected first todo to not be completed, but toggle is checked');
  }
});const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/**
 * TodoMVC - Vanilla JS
 * @planks("there are no todos")
 * @planks("{string} is not visible")
 * @planks("I see {int} todo in the list")
 * @planks("I see {int} todos in the list")
 * @planks("I press Enter")
 * @planks("the new todo has title {string}")
 * @planks("the new todo is not completed")
 * @planks("the input is cleared")
 * @planks("all todos are completed")
 * @planks("{string} is checked")
 * @planks("{string} is not checked")
 * @planks("the first todo has class {string}")
 * @planks("the todo count shows {string}")
 * @planks("the first todo has title {string}")
 * @planks("the first todo does not have class {string}")
 * @planks("I double-click the first todo label")
 * @planks("I press Enter in the edit field")
 * @planks("the editing input loses focus")
 * @planks("I press Escape in the edit field")
 * @planks("I navigate to {string}")
 * @planks("the {string} filter link has class {string}")
 */
(function () {
  'use strict';

  const STORAGE_KEY = 'todos-vanillajs';

  // ── Model ─────────────────────────────────────────────────────

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (_) {
      return [];
    }
  }

  function setTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // ── Controller ────────────────────────────────────────────────

  var ENTER_KEY = 13;

  var todoApp = {
    todos: [],
    filter: 'all',

    init: function () {
      this.todos = getTodos();
      this.filter = this.getCurrentFilter();
      this.render();
      this.bindEvents();
    },

    getCurrentFilter: function () {
      var hash = window.location.hash || '#';
      if (hash === '#/active') return 'active';
      if (hash === '#/completed') return 'completed';
      return 'all';
    },

    getFilteredTodos: function () {
      var self = this;
      return this.todos.filter(function (t) {
        if (self.filter === 'active') return !t.completed;
        if (self.filter === 'completed') return t.completed;
        return true;
      });
    },

    render: function () {
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var todoList = document.querySelector('.todo-list');
      var todoCount = document.querySelector('.todo-count');
      var clearBtn = document.querySelector('.clear-completed');
      var filters = document.querySelectorAll('.filters a');

      // Update filter link selected class
      filters.forEach(function (link) {
        var href = link.getAttribute('href');
        if ((href === '#/' && todoApp.filter === 'all') ||
            (href === '#/active' && todoApp.filter === 'active') ||
            (href === '#/completed' && todoApp.filter === 'completed')) {
          link.className = 'selected';
        } else {
          link.className = '';
        }
      });

      // Render filtered todo items from model
      todoList.innerHTML = '';
      var self = this;
      var filteredTodos = this.getFilteredTodos();
      filteredTodos.forEach(function (todo) {
        var li = document.createElement('li');
        if (todo.completed) li.className = 'completed';
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + todo.title + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + todo.title + '">';
        todoList.appendChild(li);
        // Attach blur handler to the edit input
        var editInput = li.querySelector('.edit');
        if (editInput) self.attachEditBlur(editInput);
      });

      // Update toggle-all state
      var ta = document.getElementById('toggle-all');
      if (ta) {
        ta.checked = this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
      }

      // Update counter (always based on all todos)
      if (todoCount) {
        var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
        todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';
      }

      // Show/hide clear-completed
      if (clearBtn) {
        var hasCompleted = this.todos.some(function (t) { return t.completed; });
        clearBtn.style.display = hasCompleted ? 'block' : 'none';
      }

      // Show/hide main and footer based on whether there are todos (all, not filtered)
      if (this.todos.length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      } else {
        main.style.display = 'block';
        footer.style.display = 'block';
      }
    },

    bindEvents: function () {
      var self = this;

      // Route changes
      window.addEventListener('hashchange', function () {
        self.filter = self.getCurrentFilter();
        self.render();
      });

      var newTodo = document.querySelector('.new-todo');

      if (newTodo) {
        newTodo.addEventListener('keypress', function (e) {
          if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
            var val = newTodo.value.trim();
            if (val !== '') {
              self.addTodo(val);
            }
            newTodo.value = '';
          }
        });
      }

      // Toggle all
      var toggleAll = document.getElementById('toggle-all');
      if (toggleAll) {
        toggleAll.addEventListener('change', function () {
          self.toggleAll(this.checked);
        });
      }

      // Clear completed
      var clearBtn = document.querySelector('.clear-completed');
      if (clearBtn) {
        clearBtn.addEventListener('click', function () {
          self.clearCompleted();
        });
      }

      // Delegate events on todo-list (toggle, destroy, dblclick)
      var todoList = document.querySelector('.todo-list');
      if (todoList) {
        todoList.addEventListener('change', function (e) {
          var toggle = e.target.closest('.toggle');
          if (!toggle) return;
          var li = toggle.closest('li');
          var index = Array.prototype.indexOf.call(todoList.children, li);
          if (index !== -1) {
            self.toggleTodo(index);
          }
        });

        todoList.addEventListener('click', function (e) {
          var destroy = e.target.closest('.destroy');
          if (!destroy) return;
          var li = destroy.closest('li');
          var index = Array.prototype.indexOf.call(todoList.children, li);
          if (index !== -1) {
            self.removeTodo(index);
          }
        });

        todoList.addEventListener('dblclick', function (e) {
          var label = e.target.closest('label');
          if (!label) return;
          var li = label.closest('li');
          var items = Array.prototype.indexOf.call(todoList.children, li);
          li.classList.add('editing');
          var editInput = li.querySelector('.edit');
          if (editInput) {
            editInput.value = self.todos[items].title;
            editInput.focus();
          }
