Then('no todos are completed', function () {
  const items = todoItems.call(this);
  items.forEach(function (item, i) {
    if (item.classList.contains('completed')) {
      throw new Error('Expected no todos to be completed, but todo ' + i + ' is completed');
    }
    const toggle = item.querySelector('.toggle');
    if (toggle && toggle.checked) {
      throw new Error('Expected no todos to be completed, but toggle for todo ' + i + ' is checked');
