// ── DOM identity (conformance) ─────────────────────────────────

const fs = require('node:fs');
const path = require('node:path');

Given('the application source at {string}', function (sourcePath) {
  const absPath = path.resolve(__dirname, '..', '..', sourcePath);
  if (!fs.existsSync(absPath)) {
    throw new Error('Application source not found: ' + absPath);
  }
  this._appSourcePath = absPath;
  this._appSource = fs.readFileSync(absPath, 'utf8');
  if (this._appSource.trim().length === 0) {
    throw new Error('Application source is empty: ' + absPath);
  }
});

When('the verifier checks the render function against the {string}', function (checkName) {
  if (!this._appSource) {
    throw new Error('No application source loaded. Use Given step first.');
  }
  // The render function should NOT rebuild the full list on toggle.
  // DOM node identity is preserved when the render function reuses
  // existing DOM nodes (e.g. by updating properties in place) rather
  // than destroying and recreating them via innerHTML assignment.
  // A full-list rebuild is a counterexample because every toggle would
  // destroy and recreate all DOM nodes, losing focus, scroll, and state.
  this._renderViolations = [];
  var src = this._appSource;

  // Find the render function body
  var renderMatch = src.match(/render:\s*function\s*\(\)\s*\{([\s\S]*?)\}(?=\s*,\s*\n\s*bindEvents)/);
  if (!renderMatch) {
    this._renderViolations.push('render function body not found');
    return;
  }
  var renderBody = renderMatch[1];

  // Check for innerHTML reassignment to todo-list container
  // innerHTML = '' followed by createElement/appending destroys identity
  if (/todoList\.innerHTML\s*=\s*['"]\s*['"]/.test(renderBody)) {
    this._renderViolations.push(
      'render function resets todoList.innerHTML to empty string, ' +
      'destroying all DOM node identities on every render'
    );
  }
  // Check for any innerHTML assignment in the render context
  var innerHTMLAssignments = renderBody.match(/\.innerHTML\s*=\s*/g);
  if (innerHTMLAssignments && innerHTMLAssignments.length > 0) {
    this._renderViolations.push(
      'render function uses innerHTML assignment, ' +
      'which destroys DOM node identity (' + innerHTMLAssignments.length + ' occurrences)'
    );
  }
});

Then('no counterexample showing full list rebuild is found', function () {
  if (this._renderViolations && this._renderViolations.length > 0) {
    throw new Error(
      'DOM identity violation(s) found in render function:\n  ' +
      this._renderViolations.join('\n  ')
    );
  }
});

When('the verifier checks the commitEdit and cancelEdit paths against the {string}', function (checkName) {
  if (!this._appSource) {
    throw new Error('No application source loaded. Use Given step first.');
  }
  this._editViolations = [];
  var src = this._appSource;

  // commitEdit calls this.removeTodo (for empty) or this.render()
  // render ALWAYS does innerHTML='' on todo-list -> full rebuild
  // So commitEdit always triggers full list rebuild
  this._editViolations.push(
    'commitEdit triggers full list rebuild via render() -> innerHTML reset'
  );

  // cancelEdit calls this.render() directly -> full list rebuild
  this._editViolations.push(
    'cancelEdit triggers full list rebuild via render() -> innerHTML reset'
  );

  // Check if render commits the edit on blur, even when cancelled
  // The attachEditBlur calls commitEdit on blur, but cancelEdit
  // is supposed to restore original title. If commitEdit already saved
  // the edited value on blur before cancelEdit could restore it, that
  // is a spurious blur save.
  var commitEditMatch = src.match(/commitEdit:\s*function\s*\([^)]+\)\s*\{([\s\S]*?)\}(?=\s*,\s*\n\s*cancelEdit)/);
  if (commitEditMatch) {
    var commitBody = commitEditMatch[1];
    // commitEdit calls setTodos then render; if it saves without
    // checking whether we are in a cancelled state, that is a
    // spurious save on blur
    if (/setTodos/.test(commitBody)) {
      // That's just how it works - it always persists on edit
      // It only destroys on empty; for non-empty it saves
      // The blur handler in attachEditBlur always calls commitEdit
      // The real question is: does the cancel path correctly restore?
      // cancelEdit calls render which reads from the model where
      // commitEdit already saved the edited value -> the original
      // is lost on blur even if Escape is pressed afterwards.
      this._editViolations.push(
        'attachEditBlur calls commitEdit which persists the value, ' +
        'so a subsequent Escape cannot restore the original title'
      );
    }
  }

  // Check for full list rebuild in edit paths
  var cancelEditMatch = src.match(/cancelEdit:\s*function\s*\([^)]+\)\s*\{([\s\S]*?)\}(?=\s*\};|\s*,\s*\n)/);
  if (cancelEditMatch) {
    var cancelBody = cancelEditMatch[1];
    if (/this\.render\(\)/.test(cancelBody)) {
      this._editViolations.push(
        'cancelEdit calls render() which does innerHTML reset -> full list rebuild'
      );
    }
  }
});

Then('no counterexample showing full list rebuild or spurious blur save is found', function () {
  if (this._editViolations && this._editViolations.length > 0) {
    throw new Error(
      'DOM identity violation(s) found in edit paths:\n  ' +
      this._editViolations.join('\n  ')
    );
  }
});

