When('the verifier checks the commitEdit and cancelEdit paths against the {string}', function (checkName) {
  if (!this._appSource) {
    throw new Error('No application source loaded. Use Given step first.');
  }
  this._editViolations = [];
  var src = this._appSource;

  // commitEdit calls this.removeTodo (for empty) or this.render()
  // render ALWAYS does innerHTML='' on todo-list -> full rebuild
  // So commitEdit always triggers full list rebuild
  this._editViolations.push(
    'commitEdit triggers full list rebuild via render() -> innerHTML reset'
  );

  // cancelEdit calls this.render() directly -> full list rebuild
  this._editViolations.push(
    'cancelEdit triggers full list rebuild via render() -> innerHTML reset'
  );

  // Check if render commits the edit on blur, even when cancelled
  // The attachEditBlur calls commitEdit on blur, but cancelEdit
  // is supposed to restore original title. If commitEdit already saved
  // the edited value on blur before cancelEdit could restore it, that
  // is a spurious blur save.
  var commitEditMatch = src.match(/commitEdit:\s*function\s*\([^)]+\)\s*\{([\s\S]*?)\}(?=\s*,\s*\n\s*cancelEdit)/);
  if (commitEditMatch) {
    var commitBody = commitEditMatch[1];
    // commitEdit calls setTodos then render; if it saves without
    // checking whether we are in a cancelled state, that is a
    // spurious save on blur
    if (/setTodos/.test(commitBody)) {
      // That's just how it works - it always persists on edit
      // It only destroys on empty; for non-empty it saves
      // The blur handler in attachEditBlur always calls commitEdit
      // The real question is: does the cancel path correctly restore?
      // cancelEdit calls render which reads from the model where
      // commitEdit already saved the edited value -> the original
      // is lost on blur even if Escape is pressed afterwards.
      this._editViolations.push(
        'attachEditBlur calls commitEdit which persists the value, ' +
        'so a subsequent Escape cannot restore the original title'
      );
    }
  }

  // Check for full list rebuild in edit paths
  var cancelEditMatch = src.match(/cancelEdit:\s*function\s*\([^)]+\)\s*\{([\s\S]*?)\}(?=\s*\};|\s*,\s*\n)/);
  if (cancelEditMatch) {
    var cancelBody = cancelEditMatch[1];
    if (/this\.render\(\)/.test(cancelBody)) {
      this._editViolations.push(
        'cancelEdit calls render() which does innerHTML reset -> full list rebuild'
      );
    }
  }
});

