When('the verifier checks the commitEdit and cancelEdit paths against the {string}', function (checkName) {
  if (!this._appSource) {
    throw new Error('No application source loaded. Use Given step first.');
  }
  this._editViolations = [];
  var src = this._appSource;

  // Check whether the render function preserves DOM node identity
  // by NOT using todoList.innerHTML =
  var renderMatch = src.match(/render:\s*function\s*\(\)\s*\{([\s\S]*?)\}(?=\s*,\s*\n\s*bindEvents)/);
  if (!renderMatch) {
    this._editViolations.push('render function body not found');
    return;
  }
  var renderBody = renderMatch[1];

  // Full list rebuild: check if render assigns todoList.innerHTML
  if (/todoList\.innerHTML\s*=/.test(renderBody)) {
    this._editViolations.push(
      'commitEdit triggers full list rebuild via render() -> todoList.innerHTML reset'
    );
    this._editViolations.push(
      'cancelEdit triggers full list rebuild via render() -> todoList.innerHTML reset'
    );
  }

  // Spurious blur save: check if the blur handler can commit
  // after Escape already cancelled.
  // The keydown handler removes class 'editing' before calling
  // cancelEdit or commitEdit. The focusout (blur) handler checks
  // for 'editing' class and skips if absent. This prevents
  // double-save on Escape.
  var focusoutMatch = src.match(/focusout.*\(\s*function\s*\([^)]+\)/);
  if (!focusoutMatch) {
    // No focusout handler found — check attachEditBlur instead
    var attacher = src.match(/attachEditBlur.*function\s*\([^)]+\)\s*\{([\s\S]*?)\}(?=\s*,\s*\n)/);
    if (attacher) {
      var attacherBody = attacher[1];
      if (/commitEdit/.test(attacherBody)) {
        this._editViolations.push(
          'attachEditBlur calls commitEdit unconditionally on blur, ' +
          'so a subsequent Escape cannot restore the original title'
        );
      }
    }
  } else {
    // focusout handler exists — check it guards against double-save
    var focusoutMatchFull = src.match(/todoList\.addEventListener\(\s*['"]focusout['"]\s*,\s*function\s*\([^)]+\)\s*\{([\s\S]*?)\}\s*\)/);
    if (focusoutMatchFull) {
      var focusBody = focusoutMatchFull[1];
      // Should check for 'editing' class guard
      if (!/editing/.test(focusBody)) {
        this._editViolations.push(
          'focusout/blur handler lacks editing-class guard, ' +
          'may commit after Escape'
        );
      }
      // Should NOT contain unconditional commitEdit call
      if (/commitEdit/.test(focusBody) && !/editing/.test(focusBody)) {
        this._editViolations.push(
          'focusout/blur handler calls commitEdit without guard, ' +
          'so a subsequent Escape cannot restore the original title'
        );
      }
    }
  }

  // cancelEdit should restore via render (no innerHTML reset on todo-list)
  if (!/todoList\.innerHTML\s*=/.test(renderBody)) {
    // render is identity-preserving — cancelEdit calling render
    // just restores model values on existing nodes, no rebuild
  }
});

Then('no counterexample showing full list rebuild or spurious blur save is found', function () {
  if (this._editViolations && this._editViolations.length > 0) {
    throw new Error(
      'DOM identity violation(s) found in edit paths:\n  ' +
      this._editViolations.join('\n  ')
    );
  }
});

